(()=>{const A=Abibi,page=document.body.dataset.page;let filter='all';function details(o){if(!o)return A.empty('سفارشی پیدا نشد','از منوی غذا یک سفارش نمایشی ثبت کن.');const branch=A.D.branches.find(x=>x.id===o.branch);return `<section class="surface mb-4"><div class="text-center mb-4"><div class="success-mark">✓</div><span class="badge text-bg-light">رسید نمایشی</span><h2 class="h4 mt-3">سفارشت ثبت شد!</h2><p class="small text-muted">این سفارش به شعبه ارسال نشده است.</p><strong dir="ltr">AB-${A.esc(o.number)}</strong></div><div class="summary-line"><span>شعبه</span><strong>${branch?.name||'آبی‌بی'}</strong></div><div class="summary-line"><span>روش دریافت</span><strong>${o.mode==='delivery'?'ارسال با پیک':'تحویل حضوری'}</strong></div><div class="summary-line"><span>تاریخ</span><strong>${A.date(o.date)}</strong></div>${o.scheduled?`<div class="summary-line"><span>زمان درخواستی</span><strong>${new Date(o.scheduled).toLocaleString('fa-IR')}</strong></div>`:''}${o.items.map(x=>`<div class="summary-line"><span>${A.product(x.id).name} × ${A.fa(x.qty)}${x.extra?' + افزودنی':''}</span>${A.money((A.product(x.id).price+x.extra)*x.qty)}</div>`).join('')}<div class="summary-line total"><strong>مبلغ نمایشی نهایی</strong>${A.money(o.total)}</div></section><section class="surface mb-4"><h2 class="h5 mb-4">وضعیت سفارش</h2>${['ثبت سفارش نمایشی','آماده‌سازی در شعبه','آماده تحویل','نوش جان!'].map((t,i)=>`<div class="order-step ${i===0?'active':''}"><span>${i===0?'✓':A.fa(i+1)}</span><strong>${t}</strong><p>${i===0?'ثبت در همین مرورگر انجام شد.':'مرحله نمایشی؛ وضعیت زنده نیست.'}</p></div>`).join('')}</section><div class="d-flex gap-2 flex-wrap"><button type="button" class="btn btn-primary" data-reorder="${o.id}">سفارش دوباره همین غذاها</button><a class="btn btn-outline-primary" href="orders.html">سفارش‌های من</a></div>`}function render(){if(page==='orders'){const list=A.state.orders.filter(o=>filter==='all'||o.mode===filter);A.$('#orders-list').innerHTML=list.length?list.map(o=>`<article class="surface mb-3"><div class="d-flex flex-wrap justify-content-between gap-3"><div><span class="badge text-bg-light">سفارش نمایشی</span><h2 class="h6 mt-2" dir="ltr">AB-${A.esc(o.number)}</h2><p class="text-muted small mb-0">${A.date(o.date)} · ${o.mode==='delivery'?'ارسال با پیک':'تحویل حضوری'}</p></div><div>${A.money(o.total)}<div class="mt-2"><a href="order-detail.html?id=${o.id}" class="btn btn-outline-primary btn-sm">جزئیات و پیگیری</a></div></div></div></article>`).join(''):A.empty('هنوز سفارشی نداری','یک سفارش نمایشی ثبت کن تا در اینجا نمایش داده شود.')}else{const oid=new URLSearchParams(location.search).get('id'),o=oid?A.state.orders.find(x=>x.id===oid):A.state.orders[0];A.$(page==='success'?'#receipt':'#order-detail').innerHTML=details(o)}}render();document.addEventListener('click',e=>{const f=e.target.closest('[data-orders-filter]');if(f){filter=f.dataset.ordersFilter;A.$$('[data-orders-filter]').forEach(b=>{b.classList.toggle('btn-primary',b===f);b.classList.toggle('btn-outline-primary',b!==f)});render()}const b=e.target.closest('[data-reorder]');if(b){if(A.count()){A.toast('ابتدا سبد فعلی را تکمیل یا خالی کن');return}const o=A.state.orders.find(x=>x.id===b.dataset.reorder);if(!o)return;A.state.branch=o.branch;A.state.cart=o.items.map(x=>({...x,key:A.id()}));A.save();location.href='cart.html'}})})();
